from pathlib import Path
import re

P=Path('index.html')
s=P.read_text(encoding='utf-8')

css='''
/* V4_SPECIALIST_PANEL */
.v4-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;gap:11px;margin-bottom:12px}.v4-card{background:rgba(16,26,37,.96);border:1px solid #2f4862;border-radius:16px;padding:16px}.v4-card.hero{border-color:rgba(114,168,255,.55)}.v4-table{width:100%;border-collapse:collapse;font-size:11px;margin-top:8px}.v4-table td{padding:6px 3px;border-bottom:1px solid rgba(38,56,75,.65)}.v4-table td:last-child{text-align:right}.v4-probs{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:9px}.v4-prob{background:#0c1621;border:1px solid #27394b;border-radius:9px;padding:8px;font-size:11px}@media(max-width:980px){.v4-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.v4-grid,.v4-probs{grid-template-columns:1fr}}
'''
if '/* V4_SPECIALIST_PANEL */' not in s:
    s=s.replace('</style>',css+'</style>')

funcs=r'''
/* V4_SPECIALIST_PANEL_JS */
function v4State(pass){return pass?{label:'PASS',cls:'pass'}:{label:'FAIL',cls:'fail'}}
function fourHourV4(h){if(!h||h.status!=='ok')return `<div class="v4-card hero"><div class="label">Restored 4H Specialist</div><div class="value bad">Unavailable</div></div>`;const r=h.recent_28||{},st=h.stable_96||{},rs=v4State(r.pass),ss=v4State(st.pass),overall=h.overall_status||'FAIL',oc=overall==='PASS'?'pass':overall.includes('RECENT')?'fail':'fail';return `<div class="v4-card hero"><div class="projection-status"><div class="label">Restored 4H Specialist</div><span class="pass-pill ${oc}">${overall}</span></div><div class="price">${money(h.predicted_price)}</div><div class="small">UP ${pct(h.probability_up)} • DOWN ${pct(h.probability_down)}</div><table class="v4-table"><tr><td>Earlier 28-origin test</td><td><span class="pass-pill ${rs.cls}">${rs.label}</span></td></tr><tr><td>28-origin accuracy / edge</td><td>${pct(r.directional_accuracy)} / ${pct(r.directional_edge)}</td></tr><tr><td>28-origin MAE skill</td><td>${pct(r.mae_skill_vs_baseline)}</td></tr><tr><td>Long 96-origin stability</td><td><span class="pass-pill ${ss.cls}">${ss.label}</span></td></tr><tr><td>96-origin accuracy / edge</td><td>${pct(st.directional_accuracy)} / ${pct(st.directional_edge)}</td></tr><tr><td>96-origin MAE skill</td><td>${pct(st.mae_skill_vs_baseline)}</td></tr></table><div class="small">The earlier 4H timeframe is restored, but the longer stability test remains visible so recent strength is not confused with long-run robustness.</div></div>`}
function horizonV4(row){if(!row)return `<div class="v4-card"><div class="value bad">Unavailable</div></div>`;const c=row.challenger||{},st=v4State(!!c.v4_pass);return `<div class="v4-card"><div class="projection-status"><div class="label">V4 ${row.horizon} Specialist</div><span class="pass-pill ${st.cls}">${st.label}</span></div><div class="price">${money(c.predicted_price)}</div><div class="small">UP ${pct(c.probability_up)} • ${row.selected_as_champion?'PROMOTED':'not promoted'}</div><table class="v4-table"><tr><td>Directional accuracy</td><td>${pct(c.backtest_directional_accuracy)}</td></tr><tr><td>Edge vs baseline</td><td>${pct(c.directional_edge)}</td></tr><tr><td>MAE skill</td><td>${pct(c.mae_skill_vs_baseline)}</td></tr><tr><td>OOS tests</td><td>${c.walkforward_origins||'—'}</td></tr></table></div>`}
function macroV4(m){const c=m?.macro_forecast||{},prom=!!m?.selected_as_champion;return `<div class="v4-card"><div class="projection-status"><div class="label">1Y Macro Challenger</div><span class="pass-pill ${prom?'pass':'fail'}">${prom?'PROMOTED':'FAIL'}</span></div><div class="price">${money(c.predicted_price??c.model_price)}</div><div class="small">UP ${pct(c.probability_up)} • ${c.confidence||'—'} confidence</div><table class="v4-table"><tr><td>Directional accuracy</td><td>${pct(c.backtest_directional_accuracy)}</td></tr><tr><td>Edge</td><td>${pct(c.directional_edge)}</td></tr><tr><td>MAE skill</td><td>${pct(c.mae_skill_vs_baseline)}</td></tr></table></div>`}
function meaningfulV4(mp){const rows=mp?.horizons||[];return `<div class="card" style="margin-bottom:12px"><div class="chart-title">V4 Meaningful-Move Probability</div><div class="small">UP/DOWN require a volatility-adjusted meaningful move; otherwise the model can say NO EDGE.</div><div class="v4-probs">${rows.map(x=>`<div class="v4-prob"><b>${x.horizon_days}D • ${x.signal||'NO EDGE'}</b><div>DOWN ${pct(x.probability_down)}</div><div>NO EDGE ${pct(x.probability_no_edge)}</div><div>UP ${pct(x.probability_up)}</div><div class="${x.pass?'good':'bad'}">${x.pass?'PASS':'FAIL'}</div></div>`).join('')||'<div class="small">V4 probability data unavailable.</div>'}</div></div>`}
function v4Panel(h4,hs,mp,macro){const by=Object.fromEntries((hs?.horizons||[]).map(x=>[x.horizon,x]));return `<div class="section-title">V4 Specialist Lab <span class="section-kicker">4H restored • 1D/1W specialists • 1Y macro • meaningful-move probabilities</span></div><section class="v4-grid">${fourHourV4(h4)}${horizonV4(by['1 Day'])}${horizonV4(by['1 Week'])}${macroV4(macro)}</section>${meaningfulV4(mp)}<div class="note">Challengers remain visible even when they fail. They cannot replace a champion unless the frozen out-of-sample promotion rule is met.</div>`}
'''
if '/* V4_SPECIALIST_PANEL_JS */' not in s:
    s=s.replace('function tradingViewSection(asset)',funcs+'\nfunction tradingViewSection(asset)')

new_load=r'''async function loadAsset(asset){const map=asset==='gold'?{f:'data/live_forecast.json',t:'data/gold_technicals.json',p:'data/gold_projections.json',r:'data/gold_regime_intraday.json',h4:'data/gold_4h_specialist.json',hs:'data/gold_horizon_specialist_v4.json',mp:'data/gold_meaningful_probability_v4.json',macro:'data/gold_macro_1y.json'}:{f:'data/silver_forecast.json',t:'data/silver_technicals.json',p:'data/silver_projections.json',r:'data/silver_regime_intraday.json',h4:'data/silver_4h_specialist.json',hs:'data/silver_horizon_specialist_v4.json',mp:'data/silver_meaningful_probability_v4.json',macro:'data/silver_macro_1y.json'},bust='?ts='+Date.now();const safe=u=>fetch(u+bust,{cache:'no-store'}).then(x=>x.ok?x.json():null).catch(()=>null);const [d,t,p,audit,r,h4,hs,mp,macro]=await Promise.all([safe(map.f),safe(map.t),safe(map.p),safe('data/model_backtest.json'),safe(map.r),safe(map.h4),safe(map.hs),safe(map.mp),safe(map.macro)]),aa=audit?.assets?.[asset]||null,f=technicalFrameworks(t||{});$('#updated').textContent='Updated '+new Date(p?.updated_utc||d?.updated_utc||Date.now()).toLocaleString();$('#app').innerHTML=simpleGuru(d||{},t||{},p||{projections:[]},aa,r)+predictionSnapshot(p||{projections:[]},aa)+v4Panel(h4,hs,mp,macro)+regimePanel(r)+tradingViewSection(asset)+supportResistance(t||{},f)+frameworks(f)+projections(p||{projections:[]},aa)+tech(t||{})+researchDesk(t||{},f)+stats(d||{})+factors(d||{});mountTradingView(asset);drawChart(t||{},asset)}
'''
s,n=re.subn(r'async function loadAsset\(asset\)\{.*?\}\nfunction auditCheat',new_load+'function auditCheat',s,count=1,flags=re.S)
if n!=1: raise RuntimeError('Could not replace loadAsset')
s=re.sub(r'<div class="eyebrow">.*?</div><h1>Metals Intelligence</h1><div class="sub">.*?</div>', '<div class="eyebrow">Gold • Silver</div><h1>Metals Intelligence</h1><div class="sub">Forecasts, technicals and model audit.</div>', s, count=1, flags=re.S)
P.write_text(s,encoding='utf-8')
print('V4 dashboard panel patched')
